#!/usr/bin/env python3
"""newband m33/m34 frontier first contacts (SECOND CENSUS) + the 34-row
kit-8 frozen registration ladder (m19..m32 z-continuations: one-past /
birth / death lifecycle rows incl. the item-9 stack-split enumerations
and the L8 family trackers) + item-11 trio lifecycle rows (m13/m15/m17)
+ even mid-slice probes (m14/m16/m18) + m31/m32 below-frontier windows
+ kit-10 future registration constants. BLIND SECOND CENSUS kit
(kit-9b).

CENSUS DISCLOSURE (2026-11-26, dated). A parallel lane of the same
hourly research task published a kit-9 census (commit c660fe15) BEFORE
this explorer was assembled; its commit subject was seen at build time:
it reports the m=33/m=34 frontier first contacts as the 21st/22nd
parity data, "30/34 FULL HIT, 4 co-split-shadow deviations, rule v2
codified". That is ALL that was known from the parallel lane when this
explorer was frozen: no .out measurement values, no README, no rule-v2
text, and no per-row outcomes of the parallel census were read before
this explorer's own frozen run completed. Known consequences,
acknowledged honestly: this census cannot claim any firsts (the
parallel census measured m=33/m=34 and every kit-8-registered row
first); its independent value is the blind replication itself, the
engine-independent agreement rate, and the second-census cross-check.

REGISTRATION PROVENANCE. Every binding candidate measured here was
registered EARLIER, engine-free, in the published kit-8 frozen output
future_slice_registration_constants (commit 7af915fb, sha-verified) and
the kit-8b log S5 observation registrations: the 34 binding candidates
were derived purely from the K0832 closed form on paper BEFORE any of
them was measured (the item-9 stack-split enumerations, the L8 family
trackers, the item-11 trio lifecycle rows and the even mid-slice probes
were registered at this build from the kit-8 item-9/item-11/lifecycle
operative rules, again engine-free). The sweep is the published x0
residual-band style: X = parts(S, m, 3) nondecreasing with X[0] == m
(co-token m allowed), arity <= 3, S in {m..smax}, smax = max(m+38, z+2)
(the four z+2 smax extensions are disclosed in the output). Everything
MEASURED is executed LIVE: no value field is copied from any output.
The embedded engine is the byte-clone published chain ENGINE_BLOCK
(startup pin sha256
bd5f22e415a78368c9b798296bc84948d5637decbf3c21a92404d45fb12e3a92,
i.e. engine_block.py sha256
582c93c17bcd4fa618bfb74c733c3d679e197e8749ec4bbcc8821d3a6610d5c0 minus
its import line; asserted LIVE at every startup).

Protocol caveats (unchanged): no universal claim is made; the K0832
closed form remains the only PROVED statement; every item this script
emits is finite machine observation; the standard 11x11 cell remains
UNKNOWN at all times; the four-stone root band, the 11x11 strip bands,
all closure classes and all verdict slots remain UNKNOWN; no K slot is
claimed; no residual verdict is consumed.
"""
import hashlib
import json
import sys
from functools import lru_cache

sys.setrecursionlimit(100000)

ENGINE_BLOCK = '''def mex(values):
    values = set(values)
    m = 0
    while m in values:
        m += 1
    return m

# ------------------------------------------------------------------
# Raw engines (verbatim from the published K1138 verifier block; the same
# transcription is embedded in the published y22 machine K1257).
# ------------------------------------------------------------------
@lru_cache(maxsize=6_000_000)
def H_ordered(R, X, z):
    if R == 0:
        return 0
    opts = set()
    for i, v in enumerate(X):
        if v > 1:
            opts.add(H_ordered(R - 1, X[:i] + (v - 1,) + X[i + 1:], z))
        else:
            opts.add(H_ordered(R - 1, X[:i] + X[i + 1:], z + 1))
    if z >= 1:
        opts.add(1 ^ H_ordered(R - 1, X, z - 1))
    return mex(opts)

@lru_cache(maxsize=6_000_000)
def H_canonical(R, X, z):
    X = tuple(sorted(X, reverse=True))
    if R == 0:
        return 0
    opts = set()
    i = 0
    while i < len(X):
        v = X[i]
        if v > 1:
            child = tuple(sorted(X[:i] + (v - 1,) + X[i + 1:], reverse=True))
            opts.add(H_canonical(R - 1, child, z))
        else:
            child = tuple(sorted(X[:i] + X[i + 1:], reverse=True))
            opts.add(H_canonical(R - 1, child, z + 1))
        while i + 1 < len(X) and X[i + 1] == v:
            i += 1
        i += 1
    if z >= 1:
        opts.add(1 ^ H_canonical(R - 1, X, z - 1))
    return mex(opts)

def vC(x, z, R):  # canonical-engine single token
    return H_canonical(R, (x,), z)
def vO(x, z, R):  # ordered-engine single token
    return H_ordered(R, (x,), z)

# ------------------------------------------------------------------
# Published K0832 single-token closed form (transcription of the published
# single_token block in the y22 machine K1257; see report provenance).
# ------------------------------------------------------------------
def q_odd(k):
    return k if k % 2 else k - 1

def single_token(x, z, R):
    if R == 0 or x <= 0:
        return 0
    if z == 0:
        return min(R, x) % 2
    if z == x:
        if R % 2 and R <= 2 * x - 1:
            return 2
        if R % 2 == 0 and R <= x - 1:
            return 0
        return x % 2
    if 1 <= z <= x - 1:
        m = q_odd(z)
        if R <= m:
            return 2 if R % 2 else 0
        if m < R < x + z:
            return (R + z) % 2
        return x % 2
    if z >= x + 1:
        m = q_odd(x)
        if R <= m:
            return 2 if R % 2 else 0
        return x % 2
    raise ValueError((x, z, R))
'''
_real_pin = hashlib.sha256(ENGINE_BLOCK.encode()).hexdigest()
PIN = 'bd5f22e415a78368c9b798296bc84948d5637decbf3c21a92404d45fb12e3a92'
if _real_pin != PIN:
    sys.stderr.write('ENGINE PIN MISMATCH ' + _real_pin + chr(10))
    sys.exit(3)
ns = {'lru_cache': lru_cache}
exec(ENGINE_BLOCK, ns)
H = ns['H_canonical']       # canonical chain engine (rows/anchors)
vOO = ns['vO']              # ordered single-token engine (battery)
vC = ns['vC']               # canonical single-token engine (battery)
single_token = ns['single_token']  # K0832 closed form (PROVED)

