def v(S, z, R):
    """published collapse convention: the closed-form single-token value
    of the SUM at the same (z, R)."""
    return single_token(S, z, R)


def parts(s, lo, arity):
    """all multisets (nondecreasing tuples) of tokens >= lo, sum s, 1..arity
    tokens (verbatim published helper of the chain explorers)."""
    out = []

    def rec(rem, k, cur):
        if rem == 0:
            if 1 <= len(cur) <= arity:
                out.append(tuple(cur))
            return
        if k == arity:
            return
        for t in range(lo, rem + 1):
            if cur and t < cur[-1]:
                continue
            cur.append(t)
            rec(rem - t, k + 1, cur)
            cur.pop()

    rec(s, 0, [])
    return out


def row_record_x0(spec):
    """published residual-band record style: X = parts(S, m, 3) with
    X[0] == m, i.e. all parts >= m with co-token m allowed, arity <= 3
    TOTAL. Shape-for-shape comparable with the published entries."""
    R, z, m, smax = spec['R'], spec['z'], spec['min'], spec['smax']
    H.cache_clear()
    sep = []
    scnt = 0
    for S in range(m, smax + 1):
        for X in parts(S, m, 3):
            if not X or X[0] != m:
                continue
            hv = H(R, X, z)
            ev = v(S, z, R)
            scnt += 1
            if hv != ev:
                sep.append({'X': list(X), 'S': S, 'value': hv,
                            'collapse': ev,
                            'direction': 'UP' if hv > ev else 'DOWN'})
    out = {'section': spec['section'], 'label': spec['label'], 'R': R,
           'z': z, 'min': m, 'candidate': spec['candidate'],
           'registered_by': spec['registered_by'],
           'seat_kind': spec['seat_kind'],
           'shapes': scnt, 'separations': sep}
    if spec['co_token_key']:
        out[spec['co_token_key']] = spec['co_token_val']
    return out


def emit_row(rec, spec):
    rec['style'] = spec['style']
    rec['arity_max'] = 3
    rec['s_domain'] = '{%d..%d}' % (spec['min'], spec['smax'])
    return rec


